#include "Account.h"

#include <utility>
#include <vector>

struct Account::Impl
{
    std::string owner{};
    long long balance{ 0 };
    std::vector<long long> history{};
};

Account::Account(std::string owner) : m_impl{ std::make_unique<Impl>() }
{
    m_impl->owner = std::move(owner);
}

Account::~Account() = default;
Account::Account(Account&& other) noexcept = default;
Account& Account::operator=(Account&& other) noexcept = default;

void Account::deposit(long long cents)
{
    if (cents <= 0)
    {
        return;
    }
    m_impl->balance += cents;
    m_impl->history.push_back(cents);
}

long long Account::balance() const { return m_impl->balance; }
const std::string& Account::owner() const { return m_impl->owner; }
std::size_t Account::transactionCount() const { return m_impl->history.size(); }

