unitTests:
#include "Account.h"
static_assert(sizeof(Account) == sizeof(void*), "the header should hold nothing but the one pointer");
static_assert(!std::is_copy_constructible_v<Account>);

TEST("a new account") { Account a{ "Ada" }; CHECK_EQ(a.owner(), "Ada"); CHECK_EQ(a.balance(), 0LL); CHECK_EQ(a.transactionCount(), 0u); }
TEST("deposits") { Account a{ "Ada" }; a.deposit(1500); a.deposit(250); CHECK_EQ(a.balance(), 1750LL); CHECK_EQ(a.transactionCount(), 2u); a.deposit(0); a.deposit(-40); CHECK_EQ(a.balance(), 1750LL); CHECK_EQ(a.transactionCount(), 2u); }
TEST("moving hands the implementation over") { Account a{ "Grace" }; a.deposit(900); Account b{ std::move(a) }; CHECK_EQ(b.owner(), "Grace"); CHECK_EQ(b.balance(), 900LL); Account c{ "Linus" }; c = std::move(b); CHECK_EQ(c.owner(), "Grace"); CHECK_EQ(c.transactionCount(), 1u); }
TEST("nothing leaks") { CHECK_NO_LEAK(Account a{ "Temp" }; a.deposit(1); a.deposit(2); Account b{ std::move(a) }; Account c{ "Other" }; c = std::move(b)); }

